package com.lqq.supportflow.knowledge.infrastructure.search;
import com.lqq.supportflow.knowledge.domain.*; import java.util.*; import java.util.concurrent.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="supportflow.search.elasticsearch",name="enabled",havingValue="false",matchIfMissing=true) public class InMemoryKnowledgeSearchIndex implements KnowledgeSearchIndex { private final ConcurrentMap<Long,StoredChunk> chunks=new ConcurrentHashMap<>(); public void index(Long tenantId,Long knowledgeBaseId,Long documentId,List<IndexedKnowledgeChunk> entries){entries.forEach(entry->chunks.put(entry.chunk().id(),new StoredChunk(tenantId,knowledgeBaseId,entry)));} public List<RankedKnowledgeChunk> keywordSearch(Long tenantId,Long knowledgeBaseId,String query,int limit){Set<String> terms=Set.of(query.toLowerCase(Locale.ROOT).split("\\s+"));return chunks.values().stream().filter(entry->entry.tenantId.equals(tenantId)&&entry.knowledgeBaseId.equals(knowledgeBaseId)).map(entry->rank(entry,termScore(entry.entry.chunk().content(),terms))).filter(entry->entry.score()>0).sorted(Comparator.comparingDouble(RankedKnowledgeChunk::score).reversed()).limit(limit).toList();} public List<RankedKnowledgeChunk> vectorSearch(Long tenantId,Long knowledgeBaseId,float[] query,int limit){return chunks.values().stream().filter(entry->entry.tenantId.equals(tenantId)&&entry.knowledgeBaseId.equals(knowledgeBaseId)).map(entry->rank(entry,cosine(query,entry.entry.embedding()))).sorted(Comparator.comparingDouble(RankedKnowledgeChunk::score).reversed()).limit(limit).toList();} private RankedKnowledgeChunk rank(StoredChunk source,double score){KnowledgeChunk chunk=source.entry.chunk();return new RankedKnowledgeChunk(chunk.id(),chunk.documentId(),chunk.content(),score);} private double termScore(String content,Set<String> terms){String lower=content.toLowerCase(Locale.ROOT);return terms.stream().filter(term->!term.isBlank()&&lower.contains(term)).count();} private double cosine(float[] left,float[] right){if(left.length!=right.length||left.length==0)return 0;double dot=0,leftLength=0,rightLength=0;for(int index=0;index<left.length;index++){dot+=left[index]*right[index];leftLength+=left[index]*left[index];rightLength+=right[index]*right[index];}return leftLength==0||rightLength==0?0:dot/Math.sqrt(leftLength*rightLength);} private record StoredChunk(Long tenantId,Long knowledgeBaseId,IndexedKnowledgeChunk entry) {}}
